interface KoreanTickerCode {
  code: string;
}

function validateKoreanTickerCode(code: string): boolean {
  // Korean stock ticker codes are typically 6-digit numeric strings
  // They should be exactly 6 characters long and contain only digits
  if (typeof code !== 'string') {
    return false;
  }

  // Check if the code is exactly 6 characters long
  if (code.length !== 6) {
    return false;
  }

  // Check if all characters are digits
  if (!/^\d{6}$/.test(code)) {
    return false;
  }

  return true;
}
