use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Ticker {
    pub symbol: String,
    pub exchange: Option<String>,
}

impl Ticker {
    /// Parses a ticker string into a Ticker struct.
    ///
    /// The expected format is:
    /// - `SYMBOL` (e.g., "AAPL")
    /// - `SYMBOL:EXCHANGE` (e.g., "AAPL:NASDAQ")
    ///
    /// # Examples
    ///
    /// ```
    /// let ticker = Ticker::parse("AAPL").unwrap();
    /// assert_eq!(ticker.symbol, "AAPL");
    /// assert_eq!(ticker.exchange, None);
    ///
    /// let ticker = Ticker::parse("AAPL:NASDAQ").unwrap();
    /// assert_eq!(ticker.symbol, "AAPL");
    /// assert_eq!(ticker.exchange, Some("NASDAQ".to_string()));
    /// ```
    pub fn parse(s: &str) -> Result<Ticker, String> {
        let s = s.trim();
        if s.is_empty() {
            return Err("Ticker string cannot be empty".to_string());
        }

        let parts: Vec<&str> = s.split(':').collect();

        match parts.len() {
            1 => {
                let symbol = parts[0].trim();
                if symbol.is_empty() {
                    return Err("Symbol cannot be empty".to_string());
                }
                Ok(Ticker {
                    symbol: symbol.to_string(),
                    exchange: None,
                })
            }
            2 => {
                let symbol = parts[0].trim();
                let exchange = parts[1].trim();
                if symbol.is_empty() {
                    return Err("Symbol cannot be empty".to_string());
                }
                if exchange.is_empty() {
                    return Err("Exchange cannot be empty".to_string());
                }
                Ok(Ticker {
                    symbol: symbol.to_string(),
                    exchange: Some(exchange.to_string()),
                })
            }
            _ => Err("Invalid ticker format: expected SYMBOL or SYMBOL:EXCHANGE".to_string()),
        }
    }
}

