const express = require('express');
const axios = require('axios');
const NodeCache = require('node-cache');

const router = express.Router();

// Create a cache instance with a 5-minute TTL
const cache = new NodeCache({ stdTTL: 300 });

const QUOTE_API_URL = 'https://api.quotable.io/random';

router.get('/quote', async (req, res) => {
  const cacheKey = 'random_quote';

  // Check if the quote is in the cache
  const cachedQuote = cache.get(cacheKey);
  if (cachedQuote) {
    return res.json(cachedQuote);
  }

  try {
    const response = await axios.get(QUOTE_API_URL, {
      timeout: 5000,
    });

    const quoteData = response.data;

    // Store the quote in the cache
    cache.set(cacheKey, quoteData);

    res.json(quoteData);
  } catch (error) {
    console.error('Error fetching quote:', error.message);
    res.status(500).json({ error: 'Failed to fetch quote' });
  }
});

module.exports = router;
